import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let a: Tenant; let b: Tenant;
const PAST = "2026-01-01T00:00:00.000Z";
const LATER = new Date(Date.now() + 40 * 86400000);

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  a = await createTenant("closing", "growth");
  b = await createTenant("staying", "growth");
  await memberRepo.insertMember(b.org.id, a.userIds.member, "member", null);
