    await expect(orgService.deleteOrganization(a.actors.admin, { orgId: a.org.id, confirmSlug: a.org.slug })).rejects.toThrow();

    const closed = await orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug });
    expect(closed.archivedAt).not.toBeNull();
    await expect(orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(orgService.assertCloseNotRepeated(a.userIds.owner, a.org.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(orgService.assertCloseNotRepeated(a.userIds.member, a.org.id)).resolves.toBeUndefined();

    // lists
    expect((await orgService.listOrganizationsForUser(a.userIds.member)).map(o => o.id)).toEqual([b.org.id]);
    expect(await orgService.listOrganizationsForUser(a.userIds.owner)).toEqual([]);
