    expect(await sessionService.resolveActorForOrg(principal, b.org.slug)).not.toBeNull();
    await expect(sessionService.switchActiveOrg(principal, { orgId: a.org.id })).rejects.toThrow();
    await expect(sessionService.switchActiveOrg(principal, { orgId: b.org.id })).resolves.toBeUndefined();
    expect((await sessionService.resolveSession("tok"))?.activeOrgId).toBeNull();
    expect(await memberService.resolveActor(a.userIds.member, a.org.id)).toBeNull();
    await expect(projectService.listProjects(a.actors.member, { orgId: a.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
    await expect(orgService.getOrganizationSummary(a.actors.owner, a.org.id)).rejects.toThrow();
    await expect(issueService.listIssues(a.actors.member, { orgId: a.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
    await expect(projectService.listProjects(b.actors.member, { orgId: b.org.id, limit: 10, cursor: null } as never)).resolves.toBeTruthy();

    // invitation
    const before = getDb().select().from(notifications).where(eq(notifications.orgId, a.org.id)).all().length;
    await expect(invitationService.acceptInvitation(newbie.id, { token: "inviteA" })).rejects.toThrow();
    expect(await memberRepo.findMember(a.org.id, newbie.id)).toBeNull();
    expect(await notificationService.notify(a.org.id, "member_joined", [a.userIds.owner], { title: "t", body: "b", href: "/", actorId: null })).toEqual([]);

