    console.log(tr, plans.map(p => p === a.org.id ? "A" : "B"));
    expect(plans).not.toContain(a.org.id);
    expect(getDb().select().from(activityEvents).where(eq(activityEvents.orgId, a.org.id)).all().length).toBe(usageBefore);

    expect((await runSearchReindexJob(a.org.id)).processed).toBe(0);
    expect((await runSearchReindexJob(b.org.id)).processed).toBeGreaterThan(0);
    console.log(await runUsageRollupJob(LATER), await runDigestEmailJob(LATER), await runCleanupArchivedJob(LATER));

    // slug reserved
    const again = await orgService.createOrganization(a.userIds.owner, { name: "x again", slug: a.org.slug, plan: "free" });
    expect(again.slug).not.toBe(a.org.slug);
    console.log(again.slug, (await orgService.listOrganizationsForUser(a.userIds.owner)).map(o => o.slug));
  });

  it("subscription ends at closing", async () => {
    const c = await createTenant("subs", "growth");
    await orgService.deleteOrganization(c.actors.owner, { orgId: c.org.id, confirmSlug: c.org.slug });
    const s = await subscriptionRepo.findSubscription(c.org.id);
    expect(s?.status).toBe("canceled");
    expect(s?.cancelAt).not.toBeNull();
  });
});
